SET NOCOUNT ON;
-- 2) 检查布尔/数值字段中全是 false/0 的(已同步的50条)
SELECT N'INV|是否可销售' AS k, SUM(CASE WHEN 是否可销售 IN (0) THEN 1 ELSE 0 END) AS zero_cnt, COUNT(是否可销售) AS total FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否可采购', SUM(CASE WHEN 是否可采购 IN (0) THEN 1 ELSE 0 END), COUNT(是否可采购) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否为子件', SUM(CASE WHEN 是否为子件 IN (0) THEN 1 ELSE 0 END), COUNT(是否为子件) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否为组件', SUM(CASE WHEN 是否为组件 IN (0) THEN 1 ELSE 0 END), COUNT(是否为组件) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否多单位', SUM(CASE WHEN 是否多单位 IN (0) THEN 1 ELSE 0 END), COUNT(是否多单位) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否启用保质期', SUM(CASE WHEN 是否启用保质期 IN (0) THEN 1 ELSE 0 END), COUNT(是否启用保质期) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否启用辅助属性', SUM(CASE WHEN 是否启用辅助属性 IN (0) THEN 1 ELSE 0 END), COUNT(是否启用辅助属性) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否启用称重', SUM(CASE WHEN 是否启用称重 IN (0) THEN 1 ELSE 0 END), COUNT(是否启用称重) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否序列号管理', SUM(CASE WHEN 是否序列号管理 IN (0) THEN 1 ELSE 0 END), COUNT(是否序列号管理) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否批次管理', SUM(CASE WHEN 是否批次管理 IN (0) THEN 1 ELSE 0 END), COUNT(是否批次管理) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否自制', SUM(CASE WHEN 是否自制 IN (0) THEN 1 ELSE 0 END), COUNT(是否自制) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'INV|是否倒冲领料', SUM(CASE WHEN 是否倒冲领料 IN (0) THEN 1 ELSE 0 END), COUNT(是否倒冲领料) FROM bs_inv WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'KHDA|首要联系人', SUM(CASE WHEN 首要联系人 IN (0) THEN 1 ELSE 0 END), COUNT(首要联系人) FROM dm_kh WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'KHDA|自动抵扣预收款', SUM(CASE WHEN 自动抵扣预收款 IN (0) THEN 1 ELSE 0 END), COUNT(自动抵扣预收款) FROM dm_kh WHERE 外部数据ID IS NOT NULL
UNION ALL SELECT N'GFDA|自动抵扣预收款', SUM(CASE WHEN 自动抵扣预收款 IN (0) THEN 1 ELSE 0 END), COUNT(自动抵扣预收款) FROM dm_gf WHERE 外部数据ID IS NOT NULL;
